package com.example.miniproject.controller.Member;

import com.example.miniproject.model.Tribe;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import java.util.Arrays;
import java.util.List;

@Controller
public class TribeController {

    private final List<Tribe> tribeList = Arrays.asList(

        new Tribe(1, "กะเหรี่ยง (ปกาเกอะญอ)",
            "กลุ่มชาติพันธุ์ที่มีประชากรมากที่สุดในประเทศไทย มีวิถีชีวิตผูกพันกับป่าและธรรมชาติอย่างแน่นแฟ้น โดดเด่นด้วยภูมิปัญญาการทำไร่หมุนเวียนและงานทอผ้ากี่เอวที่งดงาม",
            "ชาวปกาเกอะญอสันนิษฐานว่ามีต้นกำเนิดในแถบทางตะวันออกของทิเบตมานานกว่า 3,000 ปี ต่อมาในยุคราชวงศ์จิ๋น (พ.ศ. 207) ได้อพยพหนีภัยรุกรานจากกองทัพจีน เคลื่อนย้ายลงใต้ผ่านลุ่มแม่น้ำแยงซีเกียง มาสู่สามเหลี่ยมลุ่มแม่น้ำอิรวดีและสาละวิน จนมาตั้งถิ่นฐานสองฟากฝั่งแม่น้ำสาละวินอย่างถาวร ในศตวรรษที่ 17 เกิดการสู้รบระหว่างไทย-พม่า ทำให้กลุ่มคนเหล่านี้ถูกกวาดต้อนและอพยพเข้าสู่ไทยตามแนวตะเข็บชายแดน ปัจจุบันชาวปกาเกอะญอกระจายตัวอยู่ใน 16 จังหวัด ทั้งภาคเหนือ (เชียงใหม่ แม่ฮ่องสอน ลำพูน) และภาคตะวันตก (ตาก กาญจนบุรี) รวมประชากรกว่า 549,000 คน นับเป็นกลุ่มชาติพันธุ์ชาวเขาที่มีจำนวนมากที่สุดในประเทศไทย คำว่า 'ปกาเกอะญอ' แปลว่า 'คน' หรือ 'มนุษย์' สะท้อนศักดิ์ศรีของความเป็นมนุษย์ที่พวกเขายึดถือ",
            "ภาษาปกาเกอะญออยู่ในตระกูลทิเบต-พม่า (Tibeto-Burman) สาขาจีน-ธิเบต แต่ละกลุ่มย่อยมีภาษาพูดเฉพาะของตน อักษรดั้งเดิมเรียกว่า 'อักษรลิวา' หรืออักษรขาว ซึ่งพัฒนามาจากอักษรมอญโดยปราชญ์ชาวมอญและกะเหรี่ยงร่วมกัน ในยุคอาณานิคมมิชชันนารีตะวันตกได้พัฒนาอักษรโรมันแทนเพื่อให้เรียนรู้ได้ง่ายขึ้น ชาวปกาเกอะญอมีทั้งสำเนียงสกอร์ (Sgaw) และโพล่ง (Pwo) ซึ่งมีความแตกต่างพอสมควร ปัจจุบันยังคงมีการสอนภาษาและอักษรของตนเองในชุมชน เพื่อสืบทอดมรดกทางภาษาให้คนรุ่นใหม่",
            "วัฒนธรรมของปกาเกอะญอผูกพันกับระบบความเชื่อนับถือผี (Animism) ที่เชื่อว่าทุกสรรพสิ่งมีวิญญาณสถิตอยู่ เรียกว่า 'ต่าที ต่าเตาะ' (เทพเจ้าแห่งสัจธรรม) พิธีกรรมสำคัญได้แก่ 'ต้มคอเฮอ' หรือพิธีผูกข้อมือเรียกขวัญ และ 'กินข้าวใหม่' ที่จัดขึ้นหลังเก็บเกี่ยว เครื่องแต่งกายโดดเด่นมาก หญิงสาวและเด็กสวมชุดคลุมยาวสีขาวทอลายประดับลูกเดือย ส่วนหญิงที่แต่งงานแล้วจะเปลี่ยนเป็นเสื้อสีดำหรือน้ำเงินคู่ผ้านุ่งสีแดง งานทอผ้าบนกี่เอวเป็นภูมิปัญญาหลักที่ส่งต่อจากรุ่นสู่รุ่น ลวดลายแต่ละผืนบอกเล่าอัตลักษณ์และสถานะของผู้สวมใส่",
            "วิถีชีวิตของปกาเกอะญอผูกพันกับธรรมชาติอย่างลึกซึ้ง เป็นชนเผ่าที่มีความเชี่ยวชาญในระบบ 'ไร่หมุนเวียน' ที่ทำไร่ครั้งหนึ่งแล้วพักที่ดิน 3-7 ปีก่อนกลับมาทำใหม่ ซึ่งเป็นภูมิปัญญาในการรักษาสมดุลระบบนิเวศ ไม่ใช่ไร่เลื่อนลอยทำลายป่าอย่างที่เข้าใจผิดกัน นอกจากนี้ยังทำนาขั้นบันไดโดยใช้ระบบฝาย และเลี้ยงสัตว์ เช่น วัว ควาย หมู ไก่ ใต้ถุนบ้านยกพื้นสูง ชาวปกาเกอะญอบางชุมชนยังมีการเลี้ยงช้างเพื่อใช้งานมาแต่โบราณ ปัจจุบันปรับตัวโดยปลูกพืชเศรษฐกิจเพิ่มเติม เช่น กาแฟออร์แกนิก ผักเมืองหนาว ภายใต้โครงการหลวงและ พอช.",
            "karen.jpg"),

        new Tribe(2, "ลาหู่ (มูเซอ)",
            "นักล่าแห่งขุนเขาผู้มีความเชี่ยวชาญการพรานสัตว์โดยใช้หน้าไม้ มีความอดทนสูง และเป็นกลุ่มชาติพันธุ์ที่นับถือเทพเจ้าสูงสุดองค์เดียวอย่างเคร่งครัดมาแต่โบราณ",
            "ลาหู่ เดิมตั้งถิ่นฐานบริเวณที่ราบสูงทิเบต-ชิงไห่ มีเชื้อสายจากชาวโลโล ต่อมาเมื่อถูกรุกรานจากราชวงศ์จีนจึงอพยพลงใต้ผ่านมณฑลยูนนานเข้าสู่พม่า และทยอยเข้าประเทศไทยผ่านจังหวัดเชียงรายและเชียงใหม่ ชื่อ 'มูเซอ' มาจากภาษาพม่าว่า 'มกโซ' แปลว่า 'นายพราน' เนื่องจากชาวลาหู่มีชื่อเสียงในการล่าสัตว์ด้วยหน้าไม้อย่างแม่นยำ ในประเทศไทยมีชาวลาหู่กระจายตัวอยู่ในจังหวัดเชียงราย เชียงใหม่ และแม่ฮ่องสอน แบ่งเป็นกลุ่มย่อยหลายกลุ่ม ที่รู้จักกันดีคือ ลาหู่ดำ (ลาฮูนา) และลาหู่แดง (ลาฮูยี) ซึ่งแต่ละกลุ่มมีสำเนียงและเครื่องแต่งกายที่แตกต่างกันเล็กน้อย แต่ยังคงมีวัฒนธรรมหลักร่วมกัน",
            "ภาษาลาหู่อยู่ในตระกูลภาษาจีน-ธิเบต สาขาโลโล-พม่า มีสำเนียงแตกต่างกันตามกลุ่มย่อย ได้แก่ ลาหู่ดำ ลาหู่แดง ลาหู่เหลือง และลาหู่ขาว แต่ยังสามารถสื่อสารกันได้พอสมควร เดิมไม่มีอักษรเขียน ต่อมามิชชันนารีชาวอเมริกันได้พัฒนาอักษรโรมันสำหรับเขียนภาษาลาหู่ขึ้นในช่วงต้นคริสต์ศตวรรษที่ 20 ซึ่งยังคงใช้อยู่ในชุมชนและโบสถ์คริสต์จนถึงปัจจุบัน นอกจากภาษาลาหู่แล้ว คนรุ่นใหม่มักพูดภาษาไทยเหนือและภาษาไทยกลางได้คล่อง",
            "ลาหู่มีความเชื่อดั้งเดิมในเทพเจ้าสูงสุดองค์เดียวชื่อ 'อือซา' (G'ui-sha) ซึ่งเป็นผู้สร้างโลก ถือเป็นระบบความเชื่อแบบเทวนิยมที่หาได้ยากในกลุ่มชาติพันธุ์ชาวเขา เทศกาลใหญ่คือ 'ปีใหม่ลาหู่' ที่มีการเต้นรำ 'จะคึ' เป็นวงกลมรอบกองไฟตลอดคืน ฉลองด้วยดนตรีพื้นบ้านและการแข่งขันหน้าไม้ เครื่องแต่งกายของหญิงลาหู่ดำโดดเด่นด้วยเสื้อสีดำขลิบสีแดง ส่วนลาหู่แดงมีเครื่องแต่งกายสีสันสดใสกว่า ปัจจุบันชาวลาหู่จำนวนมากหันมานับถือศาสนาคริสต์ ทำให้วิถีชีวิตมีการผสมผสานวัฒนธรรมตะวันตกเข้ามา",
            "ชาวลาหู่อาศัยอยู่บนพื้นที่สูงระหว่าง 1,000-1,500 เมตรเหนือระดับน้ำทะเล สร้างบ้านไม้ยกพื้นสูงเป็นแถวตามแนวสันเขา ดำรงชีพด้วยการปลูกข้าวไร่ ข้าวโพด และพืชผักเมืองหนาว รวมถึงการเลี้ยงสัตว์ เช่น หมู ไก่ วัว เดิมเคยล่าสัตว์ป่าด้วยหน้าไม้และกับดักซึ่งเป็นทักษะที่สืบทอดมาแต่บรรพบุรุษ ปัจจุบันโครงการหลวงส่งเสริมให้ปลูกพืชเศรษฐกิจทดแทน เช่น ชา กาแฟ และผลไม้เมืองหนาว ชาวลาหู่ขึ้นชื่อเรื่องความสามัคคีในชุมชน มีการช่วยเหลือแรงงานกันในหมู่บ้านที่เรียกว่า 'ออกมา'",
            "lahu.jpg"),

        new Tribe(3, "ลีซู (ลีซอ)",
            "กลุ่มชาติพันธุ์ที่มีความโดดเด่นด้านการแต่งกายสีสันจัดจ้านที่สุดในบรรดาชนเผ่าไทย เครื่องเงินอันวิจิตรและชุดฉลองปีใหม่หลากสีคือสัญลักษณ์อันเป็นเอกลักษณ์ที่หาที่เปรียบมิได้",
            "ลีซูมีต้นกำเนิดบริเวณต้นน้ำแม่น้ำโขงและสาละวินในทิเบตตอนใต้ อพยพลงใต้ผ่านมณฑลยูนนานของจีนเข้าสู่พม่า และต่อมาเข้าสู่ไทยในช่วงปลายศตวรรษที่ 19 ถึงต้นศตวรรษที่ 20 ชาวลีซูมักตั้งถิ่นฐานบนสันเขาที่สูงชันระหว่าง 1,000-1,500 เมตร เพราะชื่นชอบความเป็นอิสระและอากาศเย็นสบาย ปัจจุบันพบมากในจังหวัดเชียงราย เชียงใหม่ แม่ฮ่องสอน ตาก และลำปาง ชาวลีซูมีชื่อเสียงในฐานะกลุ่มชาติพันธุ์ที่รักอิสรภาพและเคลื่อนย้ายถิ่นฐานบ่อยครั้งในอดีต เพื่อหาพื้นที่ทำกินใหม่และหลีกเลี่ยงการปกครองของรัฐ",
            "ภาษาลีซูอยู่ในตระกูลทิเบต-พม่า สาขายี่ (โลโล) ใกล้เคียงกับภาษาลาหู่และอาข่า มีสำเนียงท้องถิ่นที่แตกต่างกันเล็กน้อยระหว่างกลุ่มในจีน พม่า และไทย เดิมไม่มีอักษรเขียนของตนเอง มิชชันนารีชาวอเมริกัน James O. Fraser ได้ประดิษฐ์อักษรฟเรเซอร์ (Fraser Script) ขึ้นในช่วง ค.ศ.1915 โดยดัดแปลงจากอักษรโรมัน ใช้สัญลักษณ์พิเศษเพิ่มเติม ซึ่งได้รับการยอมรับและใช้กันอย่างแพร่หลายในชุมชนลีซูทั่วทั้งภูมิภาค ปัจจุบันมีการพิมพ์พระคัมภีร์และสื่อการเรียนการสอนด้วยอักษรฟเรเซอร์",
            "วัฒนธรรมที่โดดเด่นที่สุดของลีซูคือเทศกาล 'ปีใหม่ลีซู' หรือ 'กุ้ยฉ่า' ที่มีการฉลองยาวนาน 7-15 วัน ชาวลีซูจะแต่งกายด้วยชุดสีสันสดใสที่สุดประดับด้วยเครื่องเงินจำนวนมาก เต้นรำเป็นวงกลมประกอบเครื่องดนตรี 'ซึงลีซอ' (พิณสามสาย) และขลุ่ย ดนตรีและการเต้นรำถือเป็นหัวใจของวัฒนธรรมลีซู เครื่องเงินทั้งต่างหู สร้อยคอ กำไล และเข็มขัดเป็นสัญลักษณ์ของความมั่งคั่งและฐานะ ชุดสตรีลีซูที่สมบูรณ์หนึ่งชุดอาจมีน้ำหนักเครื่องเงินหลายกิโลกรัม นอกจากนี้ยังมีพิธีบูชาผีบรรพบุรุษและประตูหมู่บ้านศักดิ์สิทธิ์",
            "ชาวลีซูนิยมสร้างบ้านบนสันเขาสูงที่มีลมโกรก เพื่อความปลอดภัยและการมองเห็นพื้นที่โดยรอบ บ้านสร้างด้วยไม้และไม้ไผ่ ปูพื้นด้วยไม้กระดาน ดำรงชีพด้วยการปลูกข้าวไร่ ข้าวโพด ฝิ่น (เดิม) ผักและผลไม้เมืองหนาว ชาวลีซูเป็นนักค้าขายที่ขยันขันแข็ง มักพาสินค้าหัตถกรรมและของป่าลงมาขายในตลาด ผู้ชายลีซูมีทักษะการตีเหล็กและทำเครื่องมือการเกษตร ปัจจุบันชุมชนลีซูหลายแห่งพัฒนาเป็นแหล่งท่องเที่ยวเชิงวัฒนธรรม และผลิตงานหัตถกรรมเครื่องเงินส่งขายนักท่องเที่ยว",
            "lisu.jpg"),

        new Tribe(4, "อาข่า (อีก้อ)",
            "ชนเผ่าที่มีวัฒนธรรมเอกลักษณ์เข้มแข็งที่สุดกลุ่มหนึ่ง ยึดถือ 'วิถีอาข่า' หรือ 'อาข่าซาง' อย่างเคร่งครัดผ่านทุกมิติของชีวิต ตั้งแต่สถาปัตยกรรม ประเพณี ไปจนถึงการแต่งกาย",
            "ชาวอาข่าเชื่อว่าตนสืบเชื้อสายมาจากบรรพบุรุษชื่อ 'อาเผ่อมี' ที่อาศัยอยู่ในแคว้นสิบสองปันนา (มณฑลยูนนาน) มาเนิ่นนาน ต่อมาอพยพลงใต้ผ่านพม่าและรัฐฉาน เข้าสู่ไทยในช่วงปลายศตวรรษที่ 19 โดยตั้งถิ่นฐานในจังหวัดเชียงราย เชียงใหม่ และบางส่วนในลำปาง ชาวอาข่าในไทยมีประชากรประมาณ 80,000-100,000 คน กระจายอยู่ในหลายร้อยหมู่บ้านบนพื้นที่สูง พวกเขาสืบทอดวิถีดั้งเดิมไว้ได้อย่างเหนียวแน่นที่สุดในบรรดาชนเผ่าไทย ระบบการสืบทอดสายตระกูลผ่านฝ่ายบิดาและการท่องจำบรรพบุรุษสูงถึง 60-70 ชั่วอายุคนเป็นสิ่งที่ทำให้อาข่าพิเศษจากชนเผ่าอื่น",
            "ภาษาอาข่าอยู่ในตระกูลจีน-ธิเบต สาขาโลโล-พม่า ใกล้เคียงกับภาษาลีซูและลาหู่ ไม่มีอักษรเขียนดั้งเดิมของตนเอง ภูมิปัญญาและประวัติศาสตร์ถูกถ่ายทอดผ่านการบอกเล่าปากต่อปากและการร้องเพลง โดยเฉพาะ 'อาข่าปิ้เออ' หรือนักปราชญ์หมู่บ้านที่ต้องท่องจำชื่อบรรพบุรุษย้อนหลังหลายสิบชั่วอายุ ปัจจุบันมีการพัฒนาอักษรโรมันสำหรับเขียนภาษาอาข่าโดยนักภาษาศาสตร์และมิชชันนารี และมีการผลิตสื่อการเรียนการสอนสองภาษา",
            "หัวใจของวัฒนธรรมอาข่าคือ 'อาข่าซาง' (วิถีอาข่า) ซึ่งครอบคลุมกฎเกณฑ์ทุกด้านของชีวิตตั้งแต่เกิดจนตาย ประตูหมู่บ้าน 'ล้องข่อง' ทำจากไม้แกะสลักเป็นสัญลักษณ์กั้นระหว่างโลกมนุษย์กับโลกวิญญาณ และต้องสร้างใหม่ทุกปี เทศกาลใหญ่คือ 'โล้ชิงช้า' (แย้ขู่อ่าเผ่อ) ในเดือนสิงหาคม ชาวหมู่บ้านร่วมกันโล้ชิงช้าขนาดใหญ่เพื่อขอให้ผลผลิตอุดมสมบูรณ์ หมวกของสตรีอาข่าประดับด้วยเหรียญเงิน ลูกปัด และขนนก เป็นมรดกตกทอดที่มีคุณค่าทั้งทางวัฒนธรรมและทางเศรษฐกิจ ระบบ 'ดซอมา' ผู้นำพิธีกรรมทำหน้าที่ดูแลพิธีกรรมต่าง ๆ ให้ชุมชน",
            "ชาวอาข่าสร้างหมู่บ้านบนสันเขาสูงที่โล่งเตียน โดยแบ่งพื้นที่หมู่บ้านออกเป็นส่วนบนและส่วนล่างชัดเจน พร้อมด้วยลานกลางหมู่บ้านสำหรับจัดพิธีกรรม ดำรงชีพด้วยการปลูกข้าวไร่ ข้าวโพด และเลี้ยงสุกรจำนวนมาก สุกรมีความสำคัญอย่างยิ่งทั้งในการบริโภคและใช้ในพิธีกรรม สตรีอาข่าขึ้นชื่อด้านงานปักและงานเย็บผ้าประดับลูกปัดหลากสีที่วิจิตรบรรจง ปัจจุบันผลงานหัตถกรรมของอาข่าได้รับความนิยมจากนักท่องเที่ยวและตลาดสากล บางชุมชนพัฒนาเป็นแหล่งท่องเที่ยวเชิงวัฒนธรรมโดยชุมชน",
            "akha.jpg"),

        new Tribe(5, "มลาบรี (คนป่าเหลือง)",
            "ชนเผ่าดั้งเดิมที่หายากที่สุดและลึกลับที่สุดในไทย เคยใช้ชีวิตเร่ร่อนในป่าลึกโดยไม่มีที่พักถาวร โยกย้ายตามเมื่อใบตองเหลืองเปลี่ยนสี จึงได้ชื่อว่า 'คนป่าเหลือง' หรือ 'ผีตองเหลือง'",
            "มลาบรีเป็นกลุ่มชาติพันธุ์นักล่าสัตว์เก็บของป่าที่เก่าแก่ที่สุดกลุ่มหนึ่งในเอเชียตะวันออกเฉียงใต้ มีหลักฐานการอยู่อาศัยในแถบจังหวัดน่านและแพร่มาอย่างน้อยหลายร้อยปี เป็นกลุ่มชาติพันธุ์ที่มีจำนวนน้อยที่สุดในไทย ประชากรทั้งหมดเหลือเพียงประมาณ 300-400 คน คำว่า 'มลาบรี' แปลว่า 'คนป่า' หรือ 'คนแห่งป่าเขา' ในอดีตพวกเขาไม่สร้างที่อยู่ถาวร แต่ทำเพิงพักจากใบตองและกิ่งไม้ เมื่อใบตองเริ่มเหลืองจะย้ายไปตั้งเพิงใหม่ในป่าลึกกว่าเดิม วิถีชีวิตนี้ทำให้ชาวพื้นราบเรียกพวกเขาว่า 'ผีตองเหลือง' ด้วยความเชื่อว่าเป็นสัตว์ป่าหรือผี ไม่ใช่มนุษย์",
            "ภาษามลาบรีอยู่ในตระกูลออสโตรเอเชียติก สาขาขมุ เป็นภาษาที่มีเสียงวรรณยุกต์และมีคำศัพท์ที่เชื่อมโยงกับธรรมชาติสัตว์ป่าและพืชในป่าเป็นหลัก ไม่มีระบบการเขียนดั้งเดิม นักภาษาศาสตร์ Jørgen Rischel จากเดนมาร์กเป็นคนแรกที่ศึกษาและบันทึกภาษามลาบรีไว้อย่างเป็นระบบในช่วงทศวรรษ 1990 ปัจจุบันมีความพยายามบันทึกภาษาและนิทานพื้นบ้านของมลาบรีก่อนที่จะสูญหาย เพราะมีเพียงผู้สูงอายุจำนวนน้อยที่ยังพูดภาษานี้ได้อย่างคล่องแคล่ว",
            "มลาบรีมีความเชื่อดั้งเดิมเรื่องวิญญาณในธรรมชาติและผีบรรพบุรุษ ห้ามฆ่าสัตว์ที่ถือเป็นสัตว์ศักดิ์สิทธิ์ของชนเผ่า มีพิธีกรรมเรียกขวัญและรักษาโรคโดยหมอผีของชุมชน เนื่องจากใช้ชีวิตในป่า วัฒนธรรมจึงเน้นความสัมพันธ์กับธรรมชาติ ทุกชีวิตในป่ามีคุณค่าและต้องเคารพ การล่าสัตว์ต้องมีพิธีขอขมาก่อนเสมอ มลาบรีมีความรู้ด้านสมุนไพรป่าอย่างลึกซึ้ง สามารถระบุพืชสมุนไพรได้หลายร้อยชนิด ปัจจุบันชาวมลาบรีบางส่วนได้รับการดูแลจากองค์กร IMPECT และมูลนิธิต่าง ๆ เพื่อให้มีที่ดินทำกินและเข้าถึงการศึกษา",
            "วิถีชีวิตดั้งเดิมของมลาบรีคือการล่าสัตว์และเก็บของป่า ย้ายถิ่นฐานตามฤดูกาลโดยอาศัยในเพิงพักชั่วคราว ปัจจุบันหลังจากรัฐบาลไทยให้ที่ดินทำกินถาวร หลายครอบครัวเริ่มปลูกข้าวและพืชผักเป็นครั้งแรกในประวัติศาสตร์ของชนเผ่า อย่างไรก็ตาม การปรับตัวสู่วิถีเกษตรกรรมยังเป็นความท้าทาย เพราะวิถีล่าสัตว์เก็บของป่าเป็นส่วนหนึ่งของอัตลักษณ์ที่ฝังรากลึก มลาบรีมีทักษะพิเศษในการติดตามรอยสัตว์ จดจำพืชสมุนไพร และอ่านสัญญาณธรรมชาติ ซึ่งเป็นความรู้ที่มีคุณค่าและกำลังจะสูญหายไปพร้อมกับคนรุ่นเก่า",
            "mlabri.jpg"),

        new Tribe(6, "ไทลื้อ",
            "กลุ่มชาติพันธุ์ตระกูลไทที่อพยพมาจากสิบสองปันนา มีความสามารถด้านการทอผ้าที่ขึ้นชื่อที่สุดในภาคเหนือ โดยเฉพาะ 'ผ้าทอลายน้ำไหล' ที่ถือเป็นสุดยอดหัตถศิลป์ล้านนา",
            "ไทลื้อสืบเชื้อสายมาจากชาวไทกลุ่มหนึ่งที่เคยอาศัยในอาณาจักรสิบสองปันนา (ปัจจุบันคือมณฑลยูนนาน จีน) ซึ่งเป็นอาณาจักรไทโบราณที่มีความรุ่งเรืองทางวัฒนธรรมอย่างสูง การอพยพเข้าสู่ไทยเกิดขึ้นหลายระลอก ทั้งโดยสมัครใจและถูกกวาดต้อนโดยราชอาณาจักรล้านนาในช่วงศตวรรษที่ 18-19 ปัจจุบันชาวไทลื้อในไทยตั้งถิ่นฐานหนาแน่นในจังหวัดพะเยา (โดยเฉพาะอำเภอเชียงคำ) น่าน (อำเภอปัว ท่าวังผา) และเชียงราย (อำเภอเชียงของ) มีประชากรในไทยประมาณ 100,000 คน ต่างจากชนเผ่าบนดอย พวกเขาส่วนใหญ่อาศัยในหมู่บ้านที่ราบและกลมกลืนกับสังคมล้านนาอย่างดี แต่ยังคงรักษาอัตลักษณ์ทางวัฒนธรรมไว้อย่างเหนียวแน่น",
            "ภาษาไทลื้ออยู่ในตระกูลไท-กะได ใกล้เคียงกับภาษาคำเมือง (ภาษาเหนือ) และภาษาไทยกลาง มีความเข้าใจซึ่งกันได้ในระดับหนึ่งกับคนเมืองเชียงใหม่ ภาษาเขียนไทลื้อเดิมใช้ 'อักษรธรรมล้านนา' หรืออักษรฝักขาม ซึ่งสืบทอดมาจากอักษรมอญโบราณ ปัจจุบันมีความพยายามฟื้นฟูอักษรไทลื้อดั้งเดิม โดยมีการเปิดสอนในโรงเรียนชุมชนและวัดในจังหวัดน่านและพะเยา วรรณกรรมไทลื้อโบราณส่วนใหญ่บันทึกในใบลานและเก็บรักษาไว้ตามวัด",
            "วัฒนธรรมไทลื้อผสมผสานระหว่างอิทธิพลสิบสองปันนาและล้านนาอย่างลงตัว ประเพณีสำคัญได้แก่ 'ปอยหลวง' งานบวชนาคและยกช่อฟ้าวิหาร ซึ่งเป็นงานใหญ่ที่สุดของชุมชน 'สงกรานต์ไทลื้อ' ที่มีการรดน้ำดำหัวผู้ใหญ่และการแสดงพื้นบ้าน สิ่งที่ทำให้ไทลื้อโดดเด่นที่สุดคือ 'ผ้าทอลายน้ำไหล' ซึ่งเป็นผ้าฝ้ายทอมือที่มีลวดลายเลียนแบบสายน้ำไหล สีสันประกอบด้วยสีธรรมชาติจากพืช เช่น ครามและแก่นฝาง ปัจจุบันผ้าทอไทลื้อได้รับการขึ้นทะเบียนเป็นสิ่งบ่งชี้ทางภูมิศาสตร์ (GI) และเป็นที่ต้องการของตลาดทั้งในและต่างประเทศ",
            "ชาวไทลื้ออาศัยในบ้านเรือนยกพื้นสูงแบบล้านนา สร้างด้วยไม้มีหลังคาจั่วสูง หน้าบ้านตกแต่งด้วยไม้แกะสลัก ดำรงชีพด้วยการทำนาข้าวเป็นหลัก สวนผลไม้และพืชผัก หัตถกรรมทอผ้าเป็นรายได้เสริมสำคัญโดยเฉพาะผู้หญิง ชาวไทลื้อนับถือพุทธศาสนานิกายเถรวาทผสมผสานกับความเชื่อเรื่องผีบรรพบุรุษ วัดในชุมชนไทลื้อมีสถาปัตยกรรมแบบล้านนาที่งดงาม โดยเฉพาะ 'วิหารไทลื้อ' ที่มีหลังคาซ้อนชั้นและช่อฟ้าแบบเฉพาะ",
            "tailue.jpg"),

        new Tribe(7, "มอแกน (ยิปซีทะเล)",
            "ชนเผ่าเร่ร่อนทางทะเลที่อาศัยอยู่กับท้องทะเลอันดามันมาหลายร้อยปี มีทักษะการดำน้ำ เดินเรือ และอ่านสัญญาณธรรมชาติทางทะเลที่เหนือกว่ามนุษย์ทั่วไป จนได้รับการขนานนามว่า 'ยิปซีทะเล'",
            "มอแกนหรือ 'มอเก็น' (Moken) เป็นกลุ่มชาติพันธุ์ทางทะเลที่อาศัยอยู่บริเวณหมู่เกาะในทะเลอันดามันมานานหลายร้อยปี ทั้งฝั่งไทยและพม่า หลักฐานทางประวัติศาสตร์ชี้ว่าบรรพบุรุษของพวกเขาอพยพมาจากไต้หวันหรือจีนตอนใต้ผ่านทางทะเลเมื่อกว่า 4,000 ปีก่อน และดำรงชีวิตบนเรือและบนเกาะเล็กเกาะน้อยตลอดมา ในไทยพบมอแกนส่วนใหญ่ที่หมู่เกาะสุรินทร์ จังหวัดพังงา หมู่เกาะมะริด และเกาะอื่น ๆ ในทะเลอันดามัน มีประชากรในไทยเหลือเพียงประมาณ 2,000-3,000 คน เหตุการณ์สึนามิในปี 2547 ส่งผลกระทบรุนแรงต่อชุมชนมอแกน แต่มอแกนที่หมู่เกาะสุรินทร์รอดชีวิตแทบทั้งหมด เพราะอ่านสัญญาณคลื่นและนกได้ก่อนคลื่นจะถึงฝั่ง",
            "ภาษามอแกนอยู่ในตระกูลออสโตรนีเชียน สาขามาลาโย-โพลีนีเซียน ใกล้เคียงกับภาษามาเลย์และภาษาโอรังลาอูต ไม่มีระบบการเขียนดั้งเดิม ความรู้และภูมิปัญญาทางทะเลถ่ายทอดผ่านการปฏิบัติจริงและเพลงกล่อมเรือ ภาษามอแกนมีคำศัพท์เกี่ยวกับทะเล ปลา ลม คลื่น และดาราศาสตร์ทางทะเลอย่างละเอียดลึกซึ้ง ปัจจุบันนักภาษาศาสตร์กำลังเร่งบันทึกภาษามอแกนก่อนที่จะสูญหาย เนื่องจากคนรุ่นใหม่หันมาใช้ภาษาไทยในชีวิตประจำวันมากขึ้น",
            "วัฒนธรรมมอแกนเป็นอัตลักษณ์ของชนเผ่าที่อิงทะเลโดยสมบูรณ์ เทศกาลสำคัญสุดคือ 'ลอยเรือ' หรือ 'เหน่เอ็นลอ' ที่จัดขึ้นปีละครั้งในช่วงมรสุม เป็นพิธีส่งวิญญาณของผู้เสียชีวิตและสะเดาะเคราะห์ให้ชุมชน โดยสร้างเรือจำลองขนาดย่อมใส่สิ่งของแทนความทุกข์ยากแล้วปล่อยลอยทะเล ชาวมอแกนมีความเชื่อเรื่องวิญญาณทะเลและพิธีกรรมก่อนออกทะเลทุกครั้ง เด็กมอแกนเรียนรู้การดำน้ำตั้งแต่อายุ 2-3 ขวบ และสามารถดำน้ำลึกได้โดยไม่ต้องใช้อุปกรณ์ เนื่องจากมีความสามารถพิเศษในการมองใต้น้ำได้ชัดกว่าคนทั่วไป",
            "วิถีชีวิตดั้งเดิมของมอแกนคือการใช้ชีวิตบนเรือ 'กะบาง' ตลอดทั้งปี เคลื่อนย้ายตามฤดูมรสุม เมื่อมรสุมพัดแรงจึงขึ้นบกสร้างบ้านบนเสาสูงริมชายหาด หาอาหารด้วยการตกปลา ดำน้ำหาหอย ปลิงทะเล และหน้าวัว มอแกนรู้จักท้องทะเลอันดามันอย่างลึกซึ้ง สามารถอ่านดาว ลม กระแสน้ำ และพฤติกรรมสัตว์ทะเลเพื่อนำทางโดยไม่ต้องพึ่งเครื่องมือสมัยใหม่ ปัจจุบันรัฐบาลให้มอแกนอยู่อาศัยบนเกาะ ทำให้วิถีเร่ร่อนเริ่มเปลี่ยนแปลง แต่ยังคงพึ่งพิงทะเลเป็นแหล่งอาหารหลัก",
            "moken.jpg"),

        new Tribe(8, "ม้ง (แม้ว)",
            "ชนเผ่าที่มีความอดทนและความเข้มแข็งทางวัฒนธรรมสูงมาก เป็นที่รู้จักกันดีด้านศิลปะการเย็บปักถักร้อย 'ผ้าปะ' ที่สื่อเรื่องราวประวัติศาสตร์ชนเผ่า และเป็นชนเผ่าที่มีบทบาทสำคัญในประวัติศาสตร์สงครามเวียดนาม",
            "ม้งเป็นกลุ่มชาติพันธุ์ที่มีประวัติศาสตร์การต่อสู้เพื่อเอกราชอย่างยาวนาน บรรพบุรุษอาศัยอยู่ในแถบลุ่มแม่น้ำเหลืองและแม่น้ำแยงซีของจีน แต่ถูกราชวงศ์ฮั่นกดขี่และขับไล่ลงใต้อย่างต่อเนื่อง อพยพผ่านกุ้ยโจว และยูนนาน ลงสู่ลาว เวียดนาม และไทยในช่วงศตวรรษที่ 18-19 ในไทยม้งตั้งถิ่นฐานหนาแน่นในจังหวัดเชียงใหม่ (ดอยสุเทพ ดอยปุย) เชียงราย น่าน ตาก และเพชรบูรณ์ มีประชากรในไทยประมาณ 170,000 คน ในช่วงสงครามเวียดนามชาวม้งในลาวถูกสหรัฐอเมริกาสนับสนุนให้ต่อสู้กับคอมมิวนิสต์ ทำให้ม้งจำนวนมากต้องอพยพลี้ภัยสงครามมาอยู่ไทยและประเทศตะวันตกในเวลาต่อมา",
            "ภาษาม้งอยู่ในตระกูลม้ง-เมี่ยน (Hmong-Mien) ซึ่งเป็นตระกูลภาษาเอกเทศไม่เกี่ยวข้องกับตระกูลอื่น มีสำเนียงหลักสองกลุ่มคือ 'ม้งดำ' (ฮม้งเด้ว) และ 'ม้งขาว' (ฮม้งเดร์ว) ซึ่งมีความแตกต่างกันพอควรในด้านเสียงและคำศัพท์ ภาษาม้งเขียนด้วยอักษรโรมันที่พัฒนาโดย G. Linwood Barney และ William Smalley ในช่วง ค.ศ. 1950 เรียกว่า 'อักษรโรมันประยุกต์สำหรับม้ง' (RPA) และได้รับการยอมรับใช้กันอย่างแพร่หลายในชุมชนม้งทั่วโลก นอกจากนี้ยังมีอักษรปาฮาวห์ม้งที่ Shong Lue Yang ประดิษฐ์ขึ้น ซึ่งถือเป็นอักษรพื้นเมืองที่แท้จริง",
            "วัฒนธรรมม้งมีความหลากหลายและลึกซึ้ง เทศกาลใหญ่สุดคือ 'ปีใหม่ม้ง' (นอเป๊เจ่า) ในช่วงเดือนธันวาคม จัดขึ้นหลังเก็บเกี่ยวข้าว ชาวม้งแต่งกายชุดประจำเผ่าสีสันสวยงาม มีกิจกรรม 'โยนลูกช่วง' (ปอปอ) สำหรับหนุ่มสาวเพื่อหาคู่ ร้องเพลง 'เก็งลี' (เพลงรักม้ง) ด้วยแคน และเล่นลูกข่าง งานหัตถกรรมที่มีชื่อเสียงที่สุดคือ 'ผ้าปะ' (Story Cloth) ที่ปักเรื่องราวชีวิต ตำนาน และประวัติศาสตร์การอพยพลงบนผ้า ถือเป็นบันทึกประวัติศาสตร์ด้วยภาพที่ไม่มีชนเผ่าใดเทียบได้ นอกจากนี้ยังมีการทำ 'ผ้าแบ๊ะ' (Batik) ที่มีลวดลายเรขาคณิตซับซ้อน",
            "ชาวม้งอาศัยอยู่บนพื้นที่สูงระหว่าง 1,000-2,000 เมตร สร้างบ้านดินและไม้ติดดิน (ไม่ยกพื้นเหมือนชนเผ่าอื่น) ดำรงชีพด้วยการปลูกข้าวไร่ ข้าวโพด และเดิมปลูกฝิ่นเป็นพืชเศรษฐกิจ ปัจจุบันหันมาปลูกสตรอว์เบอร์รี กะหล่ำปลี พีช และกาแฟแทน โดยเฉพาะที่ดอยอินทนนท์และดอยปุยที่มีชื่อเสียงระดับโลก ชาวม้งมีความสามารถพิเศษด้านเครื่องเงิน เครื่องประดับเงินของม้งมีลวดลายประณีตละเอียดอ่อน และถือเป็นทรัพย์สินสะสมความมั่งคั่งของครอบครัว ปัจจุบันชุมชนม้งหลายแห่งบนดอยสุเทพและดอยปุยกลายเป็นแหล่งท่องเที่ยวสำคัญของจังหวัดเชียงใหม่",
            "hmong.jpg")
    );

    @GetMapping("/tribe-info")
    public String listTribes(Model model) {
        model.addAttribute("tribes", tribeList);
        return "tribe-list";
    }

    @GetMapping("/tribe-info/{id}")
    public String tribeDetail(@PathVariable int id, Model model) {
        Tribe selected = tribeList.stream()
                .filter(t -> t.getId() == id)
                .findFirst().orElse(null);
        model.addAttribute("tribe", selected);
        return "tribe-detail";
    }
}